-- Part B (batch 1/4): import specifiche in public.product_specs. Match SOLO per nome.
-- Payload jsonb codificato base64 (canale ASCII byte-fedele) per evitare ambiguita Unicode (micro sign U+00B5 vs greek mu U+03BC, en-dash, apici, ecc.).
-- Guard MD5 per-chunk sui chunk base64; guard MD5 row-level sul payload decodificato. Righe 'Nessun dato' escluse; ordine 0-based per prodotto (precalcolato).
do $mig$
declare
  expected text := 'cd4524ee3c4566e0ba408610278262fa';
  got text; b64 text; payload jsonb; bad int; n_ins int;
begin
  create temp table _b64(seq int primary key, md5 text, data text) on commit drop;
  insert into _b64(seq, md5, data) values
    (1, '75bd91c3dac30e270c999e242c86c45d', $c$$c$),
    (2, '673a7218c463c80f89ab761b3a82c8cb', $c$$c$),
    (3, '1243bc88316bcd98cdf62556ba79fdb7', $c$$c$),
    (4, 'ee7de8d272677915e390b5a598519eb9', $c$$c$),
    (5, '2de19e0292a5b61f7f0649133201e75f', $c$$c$);
  select min(seq) into bad from _b64 where md5(data) <> md5;
  if bad is not null then raise exception 'batch 1: chunk md5 mismatch at seq %', bad; end if;
  select string_agg(data, '' order by seq) into b64 from _b64;
  payload := convert_from(decode(b64, 'base64'), 'UTF8')::jsonb;
  create temp table _stg on commit drop as select n, f, v, (o)::int as o from jsonb_to_recordset(payload) as x(n text, f text, v text, o int);
  select md5(string_agg(rh, '' order by rh collate "C")) into got from (select md5(n||chr(31)||f||chr(31)||v||chr(31)||o::text) as rh from _stg) q;
  if got is distinct from expected then raise exception 'batch 1: payload integrity failed: got % expected %', got, expected; end if;
  insert into public.product_specs (product_id, campo, valore, ordine)
  select p.id, s.f, s.v, s.o from _stg s join public.products p on lower(btrim(p.canonical_name)) = lower(btrim(s.n));
  get diagnostics n_ins = row_count;
  raise notice 'specs batch 1: staged=%, inserted=%', (select count(*) from _stg), n_ins;
end
$mig$;
